/**
 * Per-language TRIGGER LEXICONS for Stage 3 context scoring.
 *
 * SPEC.md: "Maintain the trigger lexicon as per-language data files, not
 * inline code, so contributors can extend it. Cover at minimum the twenty
 * most-spoken languages."
 *
 * A trigger is a label that introduces a sensitive value — the words a person
 * or a form uses to say what the value is. Stage 3 raises a candidate's
 * confidence when one of these sits near it, which is how a bare digit run
 * becomes a recognizable national identifier.
 *
 * GENERATED, then committed, on the same terms as confusables.ts: the source
 * is a one-off multilingual authoring pass, and the committed artifact is what
 * ships. Edit this file directly to add or correct a term — it is ordinary
 * TypeScript and contributors are expected to.
 *
 * Coverage: 24 languages, 4987 terms. Terms are stored as written;
 * matching folds case and diacritics, so a single form covers its variants.
 * For heavily inflected languages the terms lean towards stems, because a
 * trigger that only matches the nominative singular is much less useful.
 *
 * Matching runs ALL languages at once rather than gating on a detected
 * document language: real messages mix languages, and language detection on a
 * short chat message is unreliable. See core's triggers.ts for why.
 */

/** One language's triggers, keyed by the entity type each vouches for. */
export interface TriggerLexicon {
  readonly code: string;
  readonly triggers: Readonly<Record<string, readonly string[]>>;
}

